const e=[{title:"Information you share",points:["We may receive your name, contact details, and document files when you message us for support.","We use the information only to help with service selection, payment guidance, upload instructions, and report delivery."]},{title:"Document handling",points:["Documents are handled for report workflow purposes and are not intended for public sharing.","We aim to keep the process private and straightforward, and we do not ask for unnecessary details."]},{title:"Communication",points:["We may contact you on WhatsApp to confirm the selected service, plan, payment status, or delivery method.","If you message us first, we will respond using the same support channel where possible."]},{title:"Policy updates",points:["We may update this policy when the website or support workflow changes.","The most recent version on this page applies from the time it is published."]}],t=[{title:"Service scope",points:["PlagExpert provides support for report selection, WhatsApp guidance, and PDF report delivery.","Service descriptions are meant to help you choose the right workflow for your needs."]},{title:"User responsibility",points:["You are responsible for the accuracy of the document and details you share with us.","Please confirm the selected service and plan before payment or upload."]},{title:"Payments and delivery",points:["Payment steps and delivery instructions are shared through WhatsApp support.","Delivery timing may vary by file size, queue, and service type."]},{title:"Acceptable use",points:["Use the service only for lawful and appropriate academic support purposes.","Do not misuse the website, impersonate another person, or attempt to disrupt support operations."]},{title:"Limitations",points:["We aim to provide helpful guidance, but results and turnaround times may vary by case.","Nothing on this page should be read as a promise of a specific institutional outcome."]}];export{e as p,t};
